contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint fund, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (fund) + (amount)); require(fund <= 1000000000000000000000000000000); require(amount <= 1000000000000000000000000000000);
        require(fund + amount >= fund);
        require(address(this).balance >= fund + amount);
        c.Command{value: fund}(address(c), ""); if (__ESBMC_reverted()) return;
        uint bal = address(c).balance;
        require(bal == fund);
        c.multiplicate{value: amount}(address(c)); if (__ESBMC_reverted()) return;
        assert(address(c).balance == bal + amount);
    }
    receive() external payable {}
}

